class PicksBot(discord.Client):
    def __init__(self):
        intents = discord.Intents.default()
        intents.message_content = True  # needed to see screenshots and questions
        if MEMBERS_INTENT:
            intents.members = True       # only for welcome DMs; also switch it on in the developer portal
        super().__init__(intents=intents)
        self.allowed_mentions = SEC_MENTIONS   # nothing the bot sends can ping @everyone/@here/roles unless asked
        self.tree = app_commands.CommandTree(self)
        self.receipt_channels: set[int] = set()
        self.ask_cooldowns: dict[int, float] = {}

    async def setup_hook(self):
        self.receipt_channels = receipt_channel_ids()
        self.add_dynamic_items(SettleButton, LogSlipButton, FollowButton, ChallengeButton, PickemButton,
                               SlipWhoSelect,
                               SweatButton, InjuryOffButton, GPButton, CopyButton, CardSweatButton, CardKalshiButton,
                               PPSettleButton, MarketButton, TakeButton, PotdButton, TriviaButton, GuessButton,
                               ClosestButton, SquaresButton, DraftButton, NoteButton, DisputeButton, FixButton,
                               BoardButton, BootRefreshButton, SlipDraftButton, FixPickButton, TrackerButton)
        if EXTRA_ITEMS:
            self.add_dynamic_items(*EXTRA_ITEMS)
        r14_db()
        r15_db()
        try:
            await start_dashboard()
        except Exception:
            log.exception("Dashboard didn't start")
        if GUILD_ID:
            guild = discord.Object(id=int(GUILD_ID))
            self.tree.copy_global_to(guild=guild)
            await self.tree.sync(guild=guild)  # shows up instantly in that server
        else:
            await self.tree.sync()  # global: can take up to an hour to appear
        self.scheduler_task = asyncio.create_task(self.scheduler())

    def _silence_disconnect_alert(self) -> bool:
        """Cancel a pending dropout note. Returns whether a heads-up was already posted."""
        self._gateway_up = True
        self._disc_gen = getattr(self, "_disc_gen", 0) + 1
        alerted = bool(getattr(self, "_disc_alerted", False))
        self._disc_alerted = False
        return alerted

    async def _say_reconnected(self) -> None:
        if self.is_closed():
            return
        try:
            await post_alert(self, "✅ **Robot reconnected**\nDiscord is back.", ping=False)
        except Exception:
            pass

    async def on_ready(self):
        alerted = self._silence_disconnect_alert()
        log.info("Logged in as %s | version %s | update %s | Claude features: %s | receipts channels: %d",
                 self.user, BOT_VERSION, ROADMAP_NOW, "on" if ai_enabled() else "off",
                 len(self.receipt_channels))
        if alerted:
            await self._say_reconnected()
        if not getattr(self, "_boot_said", False):
            try:
                landed = await announce_boot(self)
            except Exception:
                log.exception("Boot announce failed")
                landed = ""
            if landed is None or landed:
                self._boot_said = True
            else:
                asyncio.create_task(self._retry_boot())

    async def _retry_boot(self) -> None:
        """The first ready can fire before the recap channel is in hand."""
        await asyncio.sleep(8)
        if getattr(self, "_boot_said", False) or self.is_closed():
            return
        try:
            landed = await announce_boot(self)
        except Exception:
            log.exception("Boot announce failed")
            return
        if landed is None or landed:
            self._boot_said = True

    async def on_disconnect(self):
        try:
            set_setting(0, "bot_disconnect_at", now_iso())
        except Exception:
            pass
        self._gateway_up = False
        crash_note("bot", "Robot disconnected", "Lost the Discord websocket. It will try to reconnect.")
        gen = getattr(self, "_disc_gen", 0) + 1
        self._disc_gen = gen
        asyncio.create_task(self._disconnect_alert(gen))

    async def _disconnect_alert(self, gen: int) -> None:
        """A gateway blink reconnects in a few seconds. Only speak up if it stays down."""
        await asyncio.sleep(20)
        if gen != getattr(self, "_disc_gen", 0):
            return
        if getattr(self, "_gateway_up", False) or self.is_closed():
            return
        last = getattr(self, "_disc_ping_at", 0)
        if time.monotonic() - last < 600:
            return
        self._disc_ping_at = time.monotonic()
        self._disc_alerted = True
        try:
            await asyncio.wait_for(
                crash_notify(self, "bot", "Robot disconnected",
                             "Lost the Discord websocket. It will try to reconnect."), 8)
        except Exception:
            pass

    async def on_resumed(self):
        alerted = self._silence_disconnect_alert()
        crash_note("ok", "Robot reconnected", "Discord websocket is back.")
        if alerted:
            await self._say_reconnected()

    async def close(self):
        self._silence_disconnect_alert()
        try:
            set_setting(0, "bot_stopping", now_iso())
            last_done = ""
            best_ok = ""
            for jname, jh in JOB_HEALTH.items():
                ok_at = jh.get("ok_at") or ""
                if ok_at >= best_ok:
                    best_ok, last_done = ok_at, jname
            done = f" Last job that finished: {last_done}." if last_done else " No background job had finished yet."
            await asyncio.wait_for(
                post_alert(self, f"🛠️ **PIMP-BOT is going down**\nUpdate or restart. Version was {BOT_VERSION}. "
                           f"It should be back in a minute.{done}"), 5)
        except Exception:
            log.info("Couldn't post going-down note")
        await super().close()

    # ---- scheduled posts ---------------------------------------------------

    async def scheduler(self):
        await self.wait_until_ready()
        try:
            n = await refresh_guides(self)
            if n:
                log.info("Refreshed %d posted guide(s) for version %s", n, BOT_VERSION)
        except Exception:
            log.exception("Guide refresh failed")
        while not self.is_closed():
            try:
                await self.run_schedules()
            except Exception as exc:
                log.exception("Scheduled post failed")
                try:
                    await crash_notify(self, "crash", "Scheduler crashed",
                                      f"{type(exc).__name__}: {exc}"[:180])
                except Exception:
                    crash_note("crash", "Scheduler crashed", f"{type(exc).__name__}: {exc}"[:180])
            await asyncio.sleep(120)

    async def run_autograde(self, now: Optional[datetime] = None, limit: int = 3):
        """Grade picks that are still open AUTOGRADE_AFTER_HOURS after being logged."""
        if not AUTOGRADE_AFTER_HOURS:
            return
        now = now or datetime.now(timezone.utc)
        due = (now - timedelta(hours=AUTOGRADE_AFTER_HOURS)).isoformat(timespec="seconds")
        retry = (now - timedelta(hours=12)).isoformat(timespec="seconds")
        rows = db().execute(
            """SELECT * FROM picks WHERE status = 'open' AND created_at <= ?
               AND COALESCE(autograde_tries, 0) < ? AND (autograde_at IS NULL OR autograde_at <= ?)
               AND (NOT EXISTS (SELECT 1 FROM legs l WHERE l.pick_id = picks.id)
                    OR EXISTS (SELECT 1 FROM legs l WHERE l.pick_id = picks.id AND l.status = 'open'))
               ORDER BY created_at LIMIT ?""",
            (due, AUTOGRADE_MAX_TRIES, retry, limit)).fetchall()
        for p in rows:
            count_key = f"autogrades:{now.astimezone(TZ).date().isoformat()}"
            used = int(get_setting(p["guild_id"], count_key) or 0)
            try:
                pick, lines, graded, used_ai = await autograde(
                    p["guild_id"], p["id"], allow_ai=used < AUTOGRADE_DAILY_LIMIT)
            except Exception:
                log.exception("Auto-grading pick %s failed", p["id"])
                continue
            if used_ai:  # only paid lookups count toward the daily limit
                set_setting(p["guild_id"], count_key, str(used + 1))
            final_try = (pick["autograde_tries"] or 0) >= AUTOGRADE_MAX_TRIES
            if not lines or (not graded and not final_try):
                continue  # nothing new to say; try again later
            channel_id = get_setting(p["guild_id"], "recap_channel")
            channel = self.get_channel(int(channel_id)) if channel_id else None
            if channel is not None and not sec_secret(pick):
                mention = f"<@{pick['bettor_id']}> " if pick["bettor_id"] else ""
                for chunk in split_message(mention + grading_message(pick, lines, final_try)):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions(
                        everyone=False, roles=False, users=True))

    async def run_lock_grading(self, now: Optional[datetime] = None, limit: int = 3):
        """Grade locks of the week the same way as picks: 48 hours after they're submitted."""
        if not AUTOGRADE_AFTER_HOURS:
            return
        now = now or datetime.now(timezone.utc)
        due = iso(now - timedelta(hours=AUTOGRADE_AFTER_HOURS))
        retry = iso(now - timedelta(hours=12))
        rows = db().execute(
            """SELECT * FROM locks WHERE status = 'open' AND created_at <= ?
               AND COALESCE(autograde_tries, 0) < ? AND (autograde_at IS NULL OR autograde_at <= ?)
               ORDER BY created_at LIMIT ?""", (due, AUTOGRADE_MAX_TRIES, retry, limit)).fetchall()
        for r in rows:
            count_key = f"autogrades:{now.astimezone(TZ).date().isoformat()}"
            used = int(get_setting(r["guild_id"], count_key) or 0)
            tries = (r["autograde_tries"] or 0) + 1
            db().execute("UPDATE locks SET autograde_at = ?, autograde_tries = ? WHERE id = ?",
                         (now_iso(), tries, r["id"]))
            db().commit()
            like = {"id": -r["id"], "created_at": r["created_at"], "platform": "a weekly pick contest",
                    "sport": r["sport"], "description": r["text"], "notes": None}
            try:
                by_n, used_ai = await lookup_items(like, [(1, r["text"])], True,
                                                   used < AUTOGRADE_DAILY_LIMIT, context_legs=[])
            except Exception:
                log.exception("Grading lock %s failed", r["id"])
                continue
            if used_ai:
                set_setting(r["guild_id"], count_key, str(used + 1))
            res = by_n.get(1) or {}
            result = str(res.get("result", "unknown")).lower()
            channel_id = get_setting(r["guild_id"], "recap_channel")
            channel = self.get_channel(int(channel_id)) if channel_id else None
            if result in ("hit", "miss", "push"):
                status = {"hit": "win", "miss": "loss", "push": "push"}[result]
                settle_lock(r["id"], status, clip(str(res.get("why") or ""), 120) or None)
                if channel is not None:
                    await channel.send(
                        f"🔒 Lock graded: <@{r['user_id']}> {LOCK_ICON[status]} {clip(r['text'], 100)}"
                        + (f" · {clip(str(res.get('why')), 100)}" if res.get("why") else "")
                        + f"\n-# Wrong? Fix it with `/lockresult lock_id:{r['id']}`.",
                        allowed_mentions=discord.AllowedMentions(everyone=False, roles=False, users=True))
            elif tries >= AUTOGRADE_MAX_TRIES and channel is not None:
                await channel.send(
                    f"🔒 I couldn't grade <@{r['user_id']}>'s lock: {clip(r['text'], 100)}. "
                    f"Settle it with `/lockresult lock_id:{r['id']}`.",
                    allowed_mentions=discord.AllowedMentions(everyone=False, roles=False, users=True))

    async def check_limits(self, now: Optional[datetime] = None):
        """Private heads-up to anyone past the weekly loss limit they set, once a week."""
        now = now or datetime.now(TZ)
        week = week_id(now)
        for r in db().execute("SELECT guild_id, key, value FROM settings WHERE key LIKE 'limit:%'").fetchall():
            uid = r["key"].split(":", 1)[1]
            if get_setting(r["guild_id"], f"limitwarned:{uid}") == week:
                continue
            net = weekly_net(r["guild_id"], uid, now)
            if net > -float(r["value"]):
                continue
            set_setting(r["guild_id"], f"limitwarned:{uid}", week)
            try:
                user = await self.fetch_user(int(uid))
                await user.send(
                    f"Heads-up: you're {signed(net)} this week (since Monday), past the "
                    f"{money(float(r['value']))} weekly limit you set. Nothing's been blocked; this is just "
                    "the reminder you asked for. Change it with `/limit` in the server.")
            except Exception:
                log.info("Couldn't DM user %s about their limit", uid)

    async def run_live_grading(self, now: Optional[datetime] = None, limit: int = 40):
        """Settle picks and locks from the free scoreboard as soon as their games go final."""
        now = now or datetime.now(timezone.utc)
        recent = iso(now - timedelta(days=LIVE_WINDOW_DAYS))
        recheck = iso(now - timedelta(minutes=LIVE_RECHECK_MINUTES))
        await autopilot(self, now)
        picks = []
        for p in picks:
            db().execute("UPDATE picks SET live_checked_at = ? WHERE id = ?", (iso(now), p["id"]))
            db().commit()
            items, single = open_items(p)
            if not items or not leagues_for(p["sport"]) or not any(parse_simple_leg(t) or parse_prop_leg(t)
                                                                    for _, t in items):
                continue
            try:
                found = await free_grade(p, items)
            except Exception:
                log.exception("Live check failed for pick %s", p["id"])
                continue
            if not found:
                continue
            by_n = {n: {"result": r, "why": w} for n, (r, w) in found.items()}
            lines, _ = apply_results(p["guild_id"], p["id"], [(n, t) for n, t in items if n in by_n], by_n,
                                     single, only_graded=True)
            after = get_pick(p["guild_id"], p["id"])
            flex_hold = (after["status"] == "open" and after["platform"].lower() == "prizepicks"
                         and any(leg["status"] == "miss" for leg in get_legs(after["id"])))
            if after["status"] == "open" and not flex_hold:
                continue  # some legs done, the rest still going: say nothing yet
            channel = await recap_channel_for(self, after["guild_id"])
            if channel is not None:
                mention = f"<@{after['bettor_id']}> " if after["bettor_id"] else ""
                msg = grading_message(after, lines, False).replace("🤖 Looked up results for", "⚡ Final:", 1)
                for chunk in split_message(mention + msg):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions(
                        everyone=False, roles=False, users=True))
        locks = db().execute(
            """SELECT * FROM locks WHERE status = 'open' AND created_at >= ?
               AND (live_checked_at IS NULL OR live_checked_at <= ?) LIMIT ?""", (recent, recheck, limit)).fetchall()
        for lk in locks:
            db().execute("UPDATE locks SET live_checked_at = ? WHERE id = ?", (iso(now), lk["id"]))
            db().commit()
            if not leagues_for(lk["sport"]) or not parse_simple_leg(lk["text"]):
                continue
            like = {"id": -lk["id"], "created_at": lk["created_at"], "sport": lk["sport"], "description": lk["text"]}
            try:
                found = await free_grade(like, [(1, lk["text"])], context_legs=[])
            except Exception:
                log.exception("Live check failed for lock %s", lk["id"])
                continue
            if 1 in found:
                result, why = found[1]
                status = {"hit": "win", "miss": "loss", "push": "push"}[result]
                settle_lock(lk["id"], status, why)
                await post_lock_result(self, lk, status, why)

    async def run_game_pings(self, now: Optional[datetime] = None):
        """DM people who turned on /pings before their games start and at halftime (one DM per game)."""
        now = now or datetime.now(timezone.utc)
        users = [(r["guild_id"], int(r["key"].split(":", 1)[1]))
                 for r in db().execute("SELECT guild_id, key FROM settings WHERE key LIKE 'pings:%' AND value = 'on'")]
        recent = iso(now - timedelta(days=LIVE_WINDOW_DAYS))
        for guild_id, uid in users:
            picks = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_id = ? AND status = 'open' "
                                 "AND created_at >= ? ORDER BY id", (guild_id, uid, recent)).fetchall()
            due: dict[tuple[str, str], dict] = {}  # (event id, kind) -> {"ev", "picks"}
            for p in picks:
                try:
                    games = await games_for_pick(p)
                except Exception:
                    log.exception("Ping lookup failed for pick %s", p["id"])
                    continue
                for ev in games:
                    when = event_time(ev)
                    if when and ev["state"] == "pre" and timedelta(0) < when - now <= timedelta(minutes=PING_MINUTES):
                        kind = "start"
                    elif ev.get("status_name") == "STATUS_HALFTIME" and all(t["score"] is not None for t in ev["teams"]):
                        kind = "half"
                    else:
                        continue
                    if db().execute("SELECT 1 FROM pings WHERE pick_id = ? AND event_id = ? AND kind = ?",
                                    (p["id"], ev["id"], kind)).fetchone():
                        continue
                    due.setdefault((ev["id"], kind), {"ev": ev, "picks": []})["picks"].append(p)
            for (event_id, kind), item in due.items():
                ev, ps = item["ev"], item["picks"]
                away = next(t for t in ev["teams"] if not t["home"])
                home = next(t for t in ev["teams"] if t["home"])
                if kind == "start":
                    mins = max(1, round((event_time(ev) - now).total_seconds() / 60))
                    head = f"⏰ {away['short']} @ {home['short']} starts in {mins} min."
                else:
                    head = f"🏈 Halftime: {away['short']} {away['score']:g}, {home['short']} {home['score']:g}."
                riding = "\n".join(f"• Pick `#{p['id']}`: {clip(p['description'], 80)}" for p in ps[:10])
                db().executemany("INSERT OR IGNORE INTO pings (pick_id, event_id, kind) VALUES (?,?,?)",
                                 [(p["id"], event_id, kind) for p in ps])
                db().commit()
                try:
                    if is_quiet(guild_id, uid):
                        raise QuietHours()
                    user = await self.fetch_user(uid)
                    await user.send(f"{head} Riding on it:\n{riding}")
                except Exception:
                    log.info("Couldn't DM user %s a game ping", uid)

    async def post_today(self, now: datetime):
        for r in db().execute("SELECT guild_id, value FROM settings WHERE key = 'today_channel'").fetchall():
            today = now.date().isoformat()
            if now.hour < TODAY_HOUR or get_setting(r["guild_id"], "last_today") == today:
                continue
            set_setting(r["guild_id"], "last_today", today)
            channel = self.get_channel(int(r["value"]))
            if channel is None:
                continue
            embeds = [e for e in [await today_embed(p, now) for p in group_leagues(r["guild_id"])[:10]] if e]
            if embeds:
                await channel.send("📅 Today's games", embeds=embeds)

    async def job_alert(self, alert: Optional[str]) -> None:
        if not alert:
            return
        kind = "bot" if alert.startswith("⚠️") or "failed" in alert.lower() else "ok"
        title = "Robot job failed" if kind == "bot" else "Robot recovered"
        await crash_notify(self, kind, title, alert)

    async def run_schedules(self, now: Optional[datetime] = None):
        now = now or datetime.now(TZ)
        _last_cycle["at"] = now_iso()
        try:
            set_setting(0, "bot_heartbeat", now_iso())
        except Exception:
            pass
        for job in (self.run_live_grading, lambda n: grade_pickem_games(self, n), lambda n: post_hall_of_fame(self),
                    self.run_game_pings, lambda n: self.post_today(n.astimezone(TZ)),
                    lambda n: grade_survivor(self, n), lambda n: send_reminders(self, n),
                    lambda n: post_backups(self, n), lambda n: update_sweats(self, n),
                    lambda n: run_injury_alerts(self, n), lambda n: grade_kalshi(self, n),
                    lambda n: grade_group_parlays(self, n), lambda n: post_weekly_group_parlay(self, n),
                    lambda n: offer_pp_settlements(self, n), lambda n: one_leg_alerts(self, n),
                    lambda n: react_to_slips(self, n), lambda n: award_coins(self, n), lambda n: close_markets(self, n),
                    lambda n: takes_due(self, n), lambda n: post_potd(self, n), lambda n: grade_potd(self, n),
                    lambda n: reveal_hidden(self, n), lambda n: close_trivia(self, n), lambda n: grade_closest(self, n),
                    lambda n: run_squares(self, n), lambda n: finish_drafts(self, n),
                    lambda n: grade_player_survivor(self, n), lambda n: futures_due(self, n),
                    lambda n: announce_levels(self, n), lambda n: expire_color_roles(self, n),
                    lambda n: post_rivals(self, n), lambda n: bounty_check(self, n), lambda n: on_this_day(self, n),
                    lambda n: big_moments(self, n), lambda n: favorite_team_alerts(self, n),
                    lambda n: run_game_threads(self, n), lambda n: post_announcements(self, n),
                    lambda n: lineup_checks(self, n), lambda n: deadline_nudges(self, n),
                    lambda n: cheer_settled(self, n), lambda n: personal_milestones(self, n),
                    lambda n: update_receipts(self, n), lambda n: update_boards(self, n),
                    lambda n: voice_idle(self, n), lambda n: leg_watch(self, n),
                    lambda n: grade_ghosts(self, n), lambda n: nightly_cleanup(self, n),
                    lambda n: send_digests(self, n), lambda n: game_previews(self, n), lambda n: check_quests(self, n),
                    *[_named_job(name, fn, self) for name, fn in EXTRA_JOBS]):
            name = job_name(job)
            if job_recently_clean(name):
                continue
            try:
                await asyncio.wait_for(job(now.astimezone(timezone.utc)), timeout=SEC_JOB_TIMEOUT)
                alert = record_job(name, None)
            except asyncio.TimeoutError:
                log.warning("Live job %s ran too long", name)
                alert = record_job(name, TimeoutError(f"{name} ran too long"))
                if not alert:
                    alert = f"⚠️ Background job `{name}` ran too long and was stopped. Everything else keeps running."
            except Exception as exc:
                log.exception("Live job %s failed", name)
                alert = record_job(name, exc)
            if alert:
                await self.job_alert(alert)
        for name, step in (("run_autograde", lambda: self.run_autograde(now.astimezone(timezone.utc))),
                           ("run_lock_grading", lambda: self.run_lock_grading(now.astimezone(timezone.utc))),
                           ("check_limits", lambda: self.check_limits(now))):
            try:
                await step()
                await self.job_alert(record_job(name, None))
            except Exception as exc:
                log.exception("%s failed", name)
                await self.job_alert(record_job(name, exc))
        try:
            await announce_milestones(self, now.astimezone(timezone.utc))
        except Exception:
            log.exception("Milestones failed")
        today = now.date().isoformat()
        rows = db().execute("SELECT guild_id, value FROM settings WHERE key = 'recap_channel'").fetchall()
        for row in rows:
            guild_id, channel = row["guild_id"], self.get_channel(int(row["value"]))
            if channel is None:
                continue
            try:
                if (now.weekday() == RECAP_DAY and now.hour >= RECAP_HOUR
                        and get_setting(guild_id, "last_recap") != today):
                    set_setting(guild_id, "last_recap", today)
                    await channel.send(embed=build_recap(guild_id))
                    if get_setting(guild_id, "show") != "off":
                        try:
                            await post_show(self, guild_id, channel, now.astimezone(timezone.utc))
                        except Exception:
                            log.exception("Sunday Show failed")
                    rivals_results(guild_id, pay=True)
                    roles_line = await assign_hot_roles(self, guild_id)
                    if roles_line:
                        await channel.send(roles_line, allowed_mentions=discord.AllowedMentions.none())
                last_month = (now.replace(day=1) - timedelta(days=1))
                month_key = last_month.strftime("%Y-%m")
                if (now.day == 1 and now.hour >= REMIND_HOUR
                        and get_setting(guild_id, "last_awards") != month_key):
                    set_setting(guild_id, "last_awards", month_key)
                    await channel.send(embed=build_awards(guild_id, last_month.year, last_month.month))
                    try:
                        dog = await assign_top_dog(self, guild_id, last_month.year, last_month.month)
                        if dog:
                            await channel.send(dog, allowed_mentions=discord.AllowedMentions.none())
                    except Exception:
                        log.exception("Top Dog failed")
                if now.hour >= REMIND_HOUR and get_setting(guild_id, "last_remind") != today:
                    set_setting(guild_id, "last_remind", today)
                    text = build_reminders(guild_id)
                    if text:
                        await channel.send(text, allowed_mentions=discord.AllowedMentions(
                            everyone=False, roles=False, users=True))
                await self.job_alert(record_job("daily_posts", None))
            except Exception as exc:
                log.exception("Daily posts failed for guild %s", guild_id)
                await self.job_alert(record_job("daily_posts", exc))

    # ---- messages ----------------------------------------------------------

    async def on_member_join(self, member):
        if not member.bot:
            try:
                dash_note_kick(member.id, False)
            except Exception:
                pass
        if member.bot or get_setting(member.guild.id, "welcome") != "on":
            return
        try:
            await member.send(WELCOME_TEXT)
        except Exception:
            pass

    async def on_member_remove(self, member):
        if member.bot:
            return
        try:
            dash_note_kick(member.id, True)
        except Exception:
            log.warning("Couldn't close the dashboard for a removed member")

    async def on_message(self, message: discord.Message):
        if message.author.bot:
            return
        if message.guild is not None:
            try:
                want = get_setting(message.guild.id, "ticket_channel") or ""
                cid = "".join(c for c in str(want) if c.isdigit())
                if cid and str(getattr(message.channel, "id", "")) == cid:
                    staff_ticket_add(message.guild.id, message)
                    return
            except Exception:
                log.exception("ticket ingest")
        if message.guild is None:
            dm_images = image_attachments(message)
            if dm_images:
                for pic in dm_images[:SLIP_MAX_PICS]:
                    await handle_dm_slip(self, message, pic)
            return
        if is_ask_channel(message.channel):
            await ask_channel_message(self, message)
            return
        images = image_attachments(message)
        mentioned = self.user is not None and self.mentions_me(message)
        intent = slip_intent(getattr(message, "content", "")) if images or mentioned else "log"
        if images and (self.is_receipts_channel(message.channel) or mentioned):
            if intent == "ask":
                pics = images[:SLIP_MAX_PICS]
                if len(pics) > 1:
                    await self.review_slips(message, message, pics)
                else:
                    await self.review_slip(message, message, pics[0])
            else:
                await self.log_slips(message, images)
            return
        if mentioned and not images and getattr(message, "reference", None):
            # "@PIMP-BOT log this" (or "@PIMP-BOT thoughts?") as a reply to someone's screenshot
            ref = message.reference.resolved
            if isinstance(ref, discord.Message) and not ref.author.bot and image_attachments(ref):
                ref_pics = image_attachments(ref)[:SLIP_MAX_PICS]
                if intent == "ask":
                    if len(ref_pics) > 1:
                        await self.review_slips(message, ref, ref_pics)
                    else:
                        await self.review_slip(message, ref, ref_pics[0])
                else:
                    await self.log_slips(ref, ref_pics)
                return
        if images and intent == "log" and get_setting(message.guild.id, "receipts_all") == "on":
            await self.log_slips(message, images, quiet=True)
            return
        if mentioned and not images:
            words = text_slip_words(message)
            route = text_route(words)
            if route == "status":
                await self.slip_status(message)
                return
            if route == "log" and await self.text_log(message, words):
                return
            if route == "review" and await self.text_review(message, words):
                return
        if self.user is not None and self.is_question(message):
            await self.handle_ask(message)

    def is_receipts_channel(self, channel) -> bool:
        """The channel itself, or a thread/forum post inside a receipts channel."""
        return (getattr(channel, "id", None) in self.receipt_channels
                or getattr(channel, "parent_id", None) in self.receipt_channels)

    def mentions_me(self, message: discord.Message) -> bool:
        return bool(re.search(rf"<@!?{self.user.id}>", getattr(message, "content", None) or "")
                    or self.bot_role_ids(message))

    async def log_slips(self, message: discord.Message, images: list, quiet: bool = False):
        for attachment in images[:SLIP_MAX_PICS]:
            try:
                await self.handle_slip(message, attachment, quiet=quiet)
            except Exception as exc:
                log.exception("Slip logging failed in #%s", getattr(message.channel, "name", "?"))
                SLIP_STATE["last_error"] = (now_iso(), f"{type(exc).__name__}: {exc}"[:300])
                if quiet:
                    continue
                try:
                    await message.reply(f"⚠️ I couldn't log that slip ({type(exc).__name__}). Use `/pick` for now, "
                                        "and an admin can run `/admin check` here to see what's wrong.",
                                        mention_author=False)
                except Exception:
                    log.exception("Couldn't even reply about the failed slip (check my permissions here)")

    def bot_role_ids(self, message: discord.Message) -> set[int]:
        return {r.id for r in (getattr(message, "role_mentions", None) or [])
                if r.is_bot_managed() and r.tags and r.tags.bot_id == self.user.id}

    def is_question(self, message: discord.Message) -> bool:
        """An explicit @mention of the bot (or its role), or a reply to one of its answers.
        Replies to pick cards don't count, so "nice hit" doesn't spend a question."""
        if re.search(rf"<@!?{self.user.id}>", message.content) or self.bot_role_ids(message):
            return True
        ref = message.reference.resolved if message.reference else None
        return (isinstance(ref, discord.Message) and ref.author.id == self.user.id
                and not ref.embeds and not ref.components and bool(ref.content))

    async def handle_ask(self, message: discord.Message):
        question = re.sub(rf"<@!?{self.user.id}>", "", message.content)
        for role_id in self.bot_role_ids(message):
            question = question.replace(f"<@&{role_id}>", "")
        question = question.strip()
        if not question:
            await message.reply(
                "Ask me anything, a player, a score, the weather, or a regular question, like "
                f"`@{self.user.display_name} how has donk played on LAN lately?`",
                mention_author=False)
            return
        if not ask_enabled():
            await message.reply("Questions aren't switched on yet: add a free `GROQ_API_KEY` (console.groq.com) or "
                                "`GEMINI_API_KEY` (or an `ANTHROPIC_API_KEY`) variable to the bot on Railway.", mention_author=False)
            return
        wait = self.ask_cooldowns.get(message.author.id, 0) + ASK_COOLDOWN_SECONDS - time.monotonic()
        if wait > 0:
            await message.reply(f"Give me {int(wait) + 1}s before the next question.",
                                mention_author=False)
            return
        count_key = f"asks:{datetime.now(TZ).date().isoformat()}"
        used = int(get_setting(message.guild.id, count_key) or 0)
        if used >= ASK_DAILY_LIMIT:
            await message.reply(f"That's the server's {ASK_DAILY_LIMIT} questions for today. "
                                "Back tomorrow.", mention_author=False)
            return
        self.ask_cooldowns[message.author.id] = time.monotonic()
        set_setting(message.guild.id, count_key, str(used + 1))

        user_text = f"Question from {message.author.display_name}: {question}"
        ref = message.reference.resolved if message.reference else None
        if isinstance(ref, discord.Message) and ref.author.id == self.user.id and ref.content:
            user_text = f"They're replying to your earlier answer:\n{ref.content[:1500]}\n\n" + user_text
        context = build_ask_context(message.guild.id, str(message.author.id), question)
        if context:
            user_text += "\n\nThe group's own data:\n" + context
        system = ASK_SYSTEM.format(bot_name=self.user.display_name,
                                   today=datetime.now(TZ).strftime("%A, %B %d, %Y"))
        system += (f"\n\nYour voice in this server: {persona_prompt(message.guild.id)}.\n"
                   "Talk like a person in this group chat, not a help desk. Two to eight sentences unless they asked "
                   "for a list. Address them by name. Be specific to what they asked. On a sports question, "
                   "name the player, the number, or the game. On any other question, answer it straight and "
                   "do not drag in a player, a pick, or a game they did not ask about. "
                   "Do not answer with a pep talk that could fit any question. "
                   "For questions about the group's own results (records, profit, hit rates, who's best at "
                   "something, someone's tendencies), use the group_stats tool and only quote its numbers. "
                   "If group numbers are already in the message, quote those and do not invent a record, a profit, "
                   "or a result. 'me', "
                   "'my' and 'I' mean the person asking. Ask for a chart when comparing several groups.")
        ctx = {"guild_id": message.guild.id, "asker_key": str(message.author.id), "chart": None}
        weather_pack = None
        answer, sources = None, []
        failed = False
        token = None
        try:
            async with message.channel.typing():
                if question_is_weather(question):
                    try:
                        weather_pack = await asyncio.wait_for(answer_weather(question), timeout=14)
                    except Exception:
                        log.warning("Weather lookup failed", exc_info=True)
                        weather_pack = None
                if weather_pack and weather_pack.get("brief"):
                    user_text += ("\n\nWeather already looked up, including the city where the club is playing. "
                                  "Quote these numbers and name the game and the city. "
                                  "Do not invent a different temperature.\n" + weather_pack["brief"])
                elif question_is_weather(question):
                    named = weather_place_phrase(question)
                    if named:
                        user_text += (f"\n\nThe forecast for {named} did not come back. "
                                      "Say so. Do not invent a temperature.")
                searching = question_needs_search(question) and not weather_pack
                token = ASK_DATA.set(ctx)
                try:
                    answer, sources = await asyncio.wait_for(
                        ask_any(system, user_text, search=searching), timeout=18 if searching else 12)
                finally:
                    if token is not None:
                        ASK_DATA.reset(token)
        except Exception:
            log.exception("Question failed")
            failed = True
        if failed and not weather_pack:
            await message.reply("I couldn't get an answer just now. Try again in a minute.",
                                mention_author=False)
            return
        if failed or not answer:
            if weather_pack:
                answer = weather_pack.get("brief") or "Here's the hourly forecast."
                sources = []
        if weather_pack and weather_pack.get("now") is not None:
            shown = int(round(float(weather_pack["now"])))
            brief = weather_pack.get("brief") or ""
            if brief and not re.search(rf"\b{shown}\b", answer or ""):
                answer = brief + "\n\n" + (answer or "")
        chart_file = None
        if ctx.get("chart"):
            try:
                png = await asyncio.to_thread(locked_render, render_bars, *ctx["chart"])
                chart_file = discord.File(png, filename="chart.png")
            except Exception:
                log.exception("Chart failed")
        weather_file = None
        if weather_pack:
            try:
                png = await asyncio.to_thread(locked_render, render_weather_card, weather_pack)
                weather_file = discord.File(png, filename="weather.png")
            except Exception:
                log.exception("Weather chart failed")
        if sources:
            answer += "\n\n-# Sources: " + " · ".join(f"<{u}>" for u in sources)
        reply_file = weather_file or chart_file
        for i, chunk in enumerate(split_message(answer or "I came up empty on that one.")):
            if i == 0:
                extra = {"file": reply_file} if reply_file else {}
                await message.reply(chunk, mention_author=False,
                                    allowed_mentions=discord.AllowedMentions.none(), **extra)
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())
        if weather_file and chart_file:
            await message.channel.send(file=chart_file, allowed_mentions=discord.AllowedMentions.none())

    async def handle_slip(self, message: discord.Message, attachment: discord.Attachment, quiet: bool = False):
        if quiet and not slip_reader_on():
            return
        until = cooling_until(message.guild.id, message.author.id)
        if until:
            if not quiet:
                await sec_private_notice(message, cooloff_message(until))
            return
        slip, reason = None, None
        wait = sec_wait(message.author.id, "slip_read", "slip") if slip_reader_on() else 0
        if wait:
            if not quiet:
                await message.reply(sec_slow_text(wait), mention_author=False)
            return
        if slip_reader_on() and (attachment.size or 0) <= MAX_IMAGE_BYTES:
            async with message.channel.typing():
                slip, reason = await read_slip_raced(attachment)
            await keep_slip_photo(attachment, message.id)
        elif slip_reader_on():
            reason = f"the image is too big ({(attachment.size or 0) // 1024} KB)"
            SLIP_STATE["last_error"] = (now_iso(), f"Image too big to read ({(attachment.size or 0) // 1024} KB)")

        tagged_slip = bool(filed_under(message)) and slip_tag_ready(slip)
        if quiet and not tagged_slip and not slip_result_ready(slip) and (slip is None or slip["cost"] is None or slip.get("_unsure")):
            return  # every-channel mode: memes and charts aren't slips, stay out of the way

        # A tag posts the slip under that member. A finished win or loss is filed even when the stake did not read.
        if tagged_slip or (slip is not None and (slip_result_ready(slip) or slip_settled_ready(slip))):
            slip = slip_file_amounts(slip)
            if tagged_slip:
                slip["placed"] = True
        elif slip is not None and slip.get("_unsure") and slip.get("legs"):
            await offer_extra_slips(message, slip)
            save_slip_draft(message.guild.id, message, slip)
            free_count("scan_confirm")
            note_slip_read("unsure", who=message.author.display_name,
                           title=str(slip.get("description") or "screenshot"), url=message.jump_url)
            await message.reply(free_unsure_note(slip), embed=slip_draft_embed(slip),
                                view=slip_draft_view(message.id, review=ai_enabled(), edit=True), mention_author=False)
            return

        # Couldn't read it (or reading is off): let the poster fill in a short form.
        if slip is None or slip["cost"] is None:
            note = "Got it. Tap below to log this slip."
            if slip_reader_on():
                free_count("fail")
                note_slip_read("fail", who=message.author.display_name,
                               title=reason or "couldn't read", url=message.jump_url)
                note = (f"I couldn't read that one: {reason}. Tap below to log it by hand." if reason else
                        "I couldn't read that one cleanly. Tap below to log it by hand.")
            await message.reply(note, view=log_slip_view(message.author.id),
                                mention_author=False)
            return

        bettor = await named_bettor(message)
        dup = find_duplicate(message.guild.id, bettor.id, slip) if slip.get("placed", True) else None
        if dup is not None:
            if quiet:
                return
            await offer_extra_slips(message, slip)
            save_slip_draft(message.guild.id, message, slip)
            await message.reply(f"👀 That looks like pick `#{dup['id']}` (logged "
                                f"<t:{int(datetime.fromisoformat(dup['created_at']).timestamp())}:R>), so I didn't log it "
                                "twice. If it's really a second entry, tap below.",
                                view=slip_draft_view(message.id, review=False), mention_author=False)
            return

        if not slip.get("placed", True):
            if quiet:
                return
            await offer_extra_slips(message, slip)
            save_slip_draft(message.guild.id, message, slip)
            sent = await message.reply("🤔 This one doesn't look placed yet (it's still on the entry screen), so I didn't "
                                       "log it. Want a breakdown, or is it in?", view=slip_draft_view(message.id),
                                       mention_author=False)
            add_ghost(message.guild.id, message.author.id, message.author.display_name, message.id, message.channel.id,
                      getattr(sent, "id", None), slip)
            return

        async def reply(**kw):
            return await message.reply(mention_author=False, **kw)
        await offer_extra_slips(message, slip)
        await self.log_parsed_slip(message.guild.id, message.author, message.channel, slip, message.jump_url, reply,
                                   bettor=bettor, shot_message_id=message.id,
                                   shot_attachment_id=getattr(attachment, "id", None))

    async def log_parsed_slip(self, guild_id: int, author, channel, slip: dict, slip_url: str, reply,
                              bettor=None, announce: bool = True, shot_message_id: Optional[int] = None,
                              shot_attachment_id: Optional[int] = None) -> int:
        """Log a slip Claude already read, post its card (with the live receipt), and do the extras."""
        owner = bettor or author
        legs = [str(leg).strip() for leg in (slip.get("legs") or []) if str(leg).strip()]
        payout = slip["payout"] if slip["payout"] is not None else 0.0
        pick_id = insert_pick(
            guild_id=guild_id,
            bettor_key=str(owner.id),
            bettor_name=owner.display_name,
            bettor_id=owner.id,
            logged_by=author.id,
            platform=str(slip.get("platform") or "Other")[:40],
            sport=(str(slip["sport"])[:60] if slip.get("sport") else None),
            description=str(slip.get("description") or "Slip")[:200],
            legs="\n".join(legs) or None,
            cost=slip["cost"],
            payout=payout,
            slip_url=slip_url,
        )
        apply_slip_meta(pick_id, slip)
        bind_slip_shot(pick_id, shot_message_id, shot_attachment_id, len(legs))
        mark_staff_test(guild_id, getattr(channel, "id", None), pick_id)
        if slip["status"] != "open":
            settle_pick(guild_id, pick_id, slip["status"], slip["returned"])

        p = get_pick(guild_id, pick_id)
        note = None
        if slip.get("_cost_blank"):
            note = f"I couldn't read the amount risked. Fix it with `/edit pick_id:{pick_id}`."
        if slip["payout"] is None:
            pay = f"I couldn't read the payout. Fix it with `/edit pick_id:{pick_id}`."
            note = f"{note} {pay}" if note else pay
        if getattr(owner, "id", None) != getattr(author, "id", None):
            filed = f"Filed under **{owner.display_name}**."
            note = f"{note}\n{filed}" if note else filed
        short = re.search(r"all (\d+) picks \(I found (\d+)\)", " ".join(str(u) for u in (slip.get("_unsure") or [])))
        if short and short.group(1) != short.group(2):
            gap = f"The header said {short.group(1)} picks and {short.group(2)} read."
            note = f"{note} {gap}" if note else gap
        view = settle_view(pick_id) if p["status"] == "open" else None
        SLIP_STATE["last_ok"] = now_iso()
        logged = voice_line(guild_id, "logged", name=call_name(guild_id, owner.id, owner.display_name))
        content = "\n".join(x for x in (logged, note) if x) or None
        embed, extra = pick_embed(p), {}
        sent = None
        posted_receipt = False
        if announce:
            try:
                async with channel.typing():
                    f = await receipt_file(self, p)
                embed.set_image(url=f"attachment://{f.filename}")
                extra["files"] = [f]
                posted_receipt = True
            except Exception:
                log.warning("Receipt image failed for pick %s", pick_id, exc_info=True)
            if view is not None:
                extra["view"] = view
            sent = await reply(content=content, embed=embed, **extra)
        if getattr(sent, "id", None):
            remember_pick_msg(guild_id, pick_id, channel.id, sent.id, receipt=posted_receipt)
        if announce:
            tip = headsup_text(guild_id, str(author.id), pick_id)
            if tip and not is_quiet(guild_id, author.id):
                try:
                    await author.send(tip)
                except Exception:
                    pass
            await voice_say(self, guild_id, f"{call_name(guild_id, author.id, author.display_name)} just logged {p['description']}, "
                                            f"{money(p['cost'])} to win {money(p['payout'])}.")
        note_slip_read("clean", pick_id, who=author.display_name, title=p["description"], url=slip_url)
        try:
            await announce_stacks(self, guild_id, pick_id, channel)
        except Exception:
            log.warning("Stack check failed", exc_info=True)
        return pick_id

    async def slip_status(self, message: discord.Message):
        """'@PIMP-BOT how's my slip doing?': live receipts for the asker's open slips."""
        async with message.channel.typing():
            files, total = await slip_status_files(self, message.guild.id, message.author.id)
        if not files:
            await message.reply("You've got no open slips from the last few days. Post a screenshot (or type one: "
                                "\"@PIMP-BOT log Tatum o22.5 PRA, $10 to win $30\") to log one.", mention_author=False)
            return
        more = f" (newest {len(files)} of {total}; `/open` lists the rest)" if total > len(files) else ""
        await message.reply(f"Here's where your open slip{'s stand' if len(files) > 1 else ' stands'} right now{more}:",
                            files=files, mention_author=False)

    async def text_log(self, message: discord.Message, words: str) -> bool:
        """'@PIMP-BOT log Tatum o22.5 PRA, Brown o20.5 pts, $10 to win $30': confirm card, nothing logged yet.
        False when it isn't a slip after all (the caller then treats it as a question)."""
        until = cooling_until(message.guild.id, message.author.id)
        if until:
            await sec_private_notice(message, cooloff_message(until))
            return True
        wait = sec_wait(message.author.id, "slip_read", "slip") if ai_enabled() else 0
        if wait:
            await message.reply(sec_slow_text(wait), mention_author=False)
            return True
        async with message.channel.typing():
            slip, reason = await read_text_slip(words)
        if slip is None:
            if reason == "not_slip" and not TEXT_LOG.search(words):
                return False
            await message.reply(f"I couldn't find a slip in that{': ' + reason if reason and reason != 'not_slip' else ''}. "
                                "Try one leg per line or comma, like "
                                "`@PIMP-BOT log Tatum over 22.5 PRA, Brown over 20.5 points, $10 to win $30`.",
                                mention_author=False)
            return True
        save_slip_draft(message.guild.id, message, slip, typed=True)
        dup = find_duplicate(message.guild.id, message.author.id, slip)
        await message.reply(content=(f"👀 Heads up: this matches pick `#{dup['id']}` you already logged." if dup else None),
                            embed=slip_draft_embed(slip), view=slip_draft_view(message.id, review=ai_enabled(), edit=True),
                            mention_author=False)
        return True

    async def text_review(self, message: discord.Message, words: str) -> bool:
        """'@PIMP-BOT thoughts on Tatum o22.5 PRA + Brown o20.5?': a breakdown with the X-ray, nothing logged.
        False when it isn't a slip after all (the caller then treats it as a question)."""
        if not ai_enabled():
            return False
        wait = sec_wait(message.author.id, "slip_read", "slip")
        if wait:
            await message.reply(sec_slow_text(wait), mention_author=False)
            return True
        async with message.channel.typing():
            slip, reason = await read_text_slip(words)
        if slip is None:
            return False
        gate = ask_gate(message.guild.id, message.author.id)
        if gate:
            await message.reply(gate, mention_author=False)
            return True
        slip["placed"] = False
        save_slip_draft(message.guild.id, message, slip, typed=True)
        async with message.channel.typing():
            text, xray = await slip_review(self, message.guild.id, message.author, slip, words)
        chunks = split_message(text)
        first = None
        for k, chunk in enumerate(chunks):
            extra = {}
            if k == 0 and xray is not None:
                extra["file"] = xray
            if k == len(chunks) - 1:
                extra["view"] = slip_draft_view(message.id, review=False, edit=True)
            if k == 0:
                first = await message.reply(chunk, mention_author=False, allowed_mentions=discord.AllowedMentions.none(),
                                            **extra)
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none(), **extra)
        if find_duplicate(message.guild.id, message.author.id, dict(slip, cost=None)) is None:
            add_ghost(message.guild.id, message.author.id, message.author.display_name, message.id, message.channel.id,
                      getattr(first, "id", None), slip)
        await offer_data_picks(message, slip)
        return True

    async def review_slips(self, message: discord.Message, image_message: discord.Message, attachments: list):
        """Several photos are several slips. A tag posts each readable one, and the reply names every slip."""
        gate = ask_gate(message.guild.id, message.author.id)
        if gate:
            await message.reply(gate, mention_author=False)
            return
        pics = [a for a in attachments if (getattr(a, "size", 0) or 0) <= MAX_IMAGE_BYTES][:SLIP_MAX_PICS]
        if not pics:
            await message.reply("Those photos are too big to read. Send each slip on its own.", mention_author=False)
            return
        sem = asyncio.Semaphore(2)

        async def read_one(att):
            async with sem:
                try:
                    got = await read_slip_raced(att, budget=14)
                    await keep_slip_photo(att, image_message.id)
                    return got
                except Exception:
                    log.warning("One photo in a batch failed", exc_info=True)
                    return None, "that read failed"

        async with message.channel.typing():
            reads = await asyncio.gather(*(read_one(a) for a in pics))
        target = await named_bettor(message)
        tagged = getattr(target, "id", None) not in (None, getattr(message.author, "id", None))
        lines, posted, missed = [], 0, 0
        for i, (slip, reason) in enumerate(reads, 1):
            if not slip or not (slip.get("legs") or slip.get("description")):
                missed += 1
                why = f": {reason}" if reason else ""
                lines.append(f"**{i}.** I couldn't read that photo{why}.")
                continue
            blurb = slip_batch_blurb(i, slip)
            owner = target if tagged else message.author
            if slip_settled_ready(slip) or (tagged and slip_tag_ready(slip)):
                ready = slip_file_amounts(dict(slip))
                ready["placed"] = True
                try:
                    dup = find_duplicate(message.guild.id, owner.id, ready)
                    if dup is not None:
                        blurb += f"\nAlready on **{getattr(owner, 'display_name', 'them')}** as pick `#{dup['id']}`."
                    else:
                        async def _quiet(**kw):
                            return None
                        pid = await self.log_parsed_slip(
                            message.guild.id, message.author, message.channel, ready,
                            getattr(image_message, "jump_url", "") or "", _quiet, bettor=owner, announce=False,
                            shot_message_id=image_message.id,
                            shot_attachment_id=getattr(pics[i - 1], "id", None))
                        posted += 1
                        who_name = getattr(owner, "display_name", None) or "them"
                        blurb += f"\nPosted under **{who_name}** · pick `#{pid}`."
                        if ready.get("_cost_blank"):
                            blurb += f" The stake was blank. Fix it with `/edit pick_id:{pid}`."
                except Exception:
                    log.exception("Filing one slip from a batch failed")
                    blurb += "\nThat one did not post. Try it again on its own."
            elif tagged:
                blurb += "\nNot posted. The legs were not clear enough."
            lines.append(blurb)
        total = len(pics)
        if tagged and posted:
            intro = f"**{posted} of {total}** posted under **{target.display_name}**."
        elif posted:
            intro = f"**{posted} of {total}** logged."
        elif tagged:
            intro = f"**{total} photos.** None of them posted under **{target.display_name}**."
        else:
            intro = f"**{total} slips** in this message."
        if missed and not tagged:
            intro += f" {missed} did not read."
        text = intro + "\n\n" + "\n\n".join(lines)
        if not tagged and not posted:
            text += "\n\nTag a member on the photos to put them on a record."
        chunks = split_message(text)
        for k, chunk in enumerate(chunks):
            if k == 0:
                await message.reply(chunk, mention_author=False, allowed_mentions=discord.AllowedMentions.none())
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())

    async def review_slip(self, message: discord.Message, image_message: discord.Message, attachment):
        """A screenshot with a question gets a breakdown. Tagging a member posts the slip under their name."""
        gate = ask_gate(message.guild.id, message.author.id)
        if gate:
            await message.reply(gate, mention_author=False)
            return
        slip, reason = None, None
        question = re.sub(r"<@[!&]?\d+>", " ", getattr(message, "content", "") or "").strip()
        said = ""
        async with message.channel.typing():
            if (attachment.size or 0) <= MAX_IMAGE_BYTES:
                slip, reason = await read_slip_raced(attachment)
                await keep_slip_photo(attachment, image_message.id)
            if slip is None or not (slip.get("legs") or slip.get("description")):
                if ask_enabled():
                    try:
                        said = await asyncio.wait_for(glance_talk(
                            attachment, question, message.guild.id, message.author.display_name), timeout=8)
                    except Exception:
                        said = ""
        if slip is None or not (slip.get("legs") or slip.get("description")):
            if said:
                await message.reply(said, mention_author=False, allowed_mentions=discord.AllowedMentions.none())
                return
            free_count("fail")
            note_slip_read("fail", who=message.author.display_name,
                           title=reason or "couldn't read", url=getattr(image_message, "jump_url", "") or "")
            if reason and ("credit" in reason.lower() or "billing" in reason.lower()):
                await message.reply("I couldn't pull the legs off that screenshot. Type the names and I'll talk it through.",
                                    mention_author=False)
                return
            await message.reply(f"I couldn't read that slip{': ' + reason if reason else ''}. Try a clearer screenshot.",
                                mention_author=False)
            return
        if slip_settled_ready(slip):
            target = await named_bettor(message)
            owner = target or message.author
            ready = slip_file_amounts(dict(slip))
            ready["placed"] = True
            who = getattr(owner, "display_name", None) or "them"
            dup = find_duplicate(message.guild.id, getattr(owner, "id", 0), ready)
            if dup is not None:
                await message.reply(f"Already on **{who}** as pick `#{dup['id']}`.", mention_author=False)
                return
            async def reply(**kw):
                return await message.reply(mention_author=False, **kw)
            try:
                await self.log_parsed_slip(
                    message.guild.id, message.author, message.channel, ready,
                    getattr(image_message, "jump_url", "") or "", reply, bettor=owner,
                    shot_message_id=image_message.id, shot_attachment_id=getattr(attachment, "id", None))
            except Exception:
                log.exception("Logging a settled card failed")
            else:
                return
        save_slip_draft(message.guild.id, image_message, slip, mention_from=message)
        note_slip_read("unsure" if slip.get("_unsure") else "clean",
                       who=message.author.display_name,
                       title=str(slip.get("description") or "screenshot"),
                       url=getattr(image_message, "jump_url", "") or "")
        filed_note = ""
        target = await named_bettor(message)
        tagged = getattr(target, "id", None) not in (None, getattr(message.author, "id", None))
        if tagged and slip_tag_ready(slip):
            ready = slip_file_amounts(dict(slip))
            ready["placed"] = True
            dup = find_duplicate(message.guild.id, target.id, ready)
            if dup is not None:
                filed_note = f"Already on **{target.display_name}**'s record as pick `#{dup['id']}`."
            else:
                async def reply(**kw):
                    return await message.reply(mention_author=False, **kw)
                try:
                    pid = await self.log_parsed_slip(
                        message.guild.id, message.author, message.channel, ready,
                        getattr(image_message, "jump_url", "") or "", reply, bettor=target,
                        shot_message_id=image_message.id, shot_attachment_id=getattr(attachment, "id", None))
                    filed_note = f"Posted under **{target.display_name}** · pick `#{pid}`."
                    d = get_slip_draft(message.guild.id, image_message.id)
                    if d is not None:
                        d["used"] = pid
                        d["for_id"] = int(target.id)
                        d["for_name"] = target.display_name
                        set_setting(message.guild.id, f"draft:{image_message.id}", json.dumps(d))
                except Exception:
                    log.exception("Filing a slip under a mention failed")
        question = re.sub(r"<@[!&]?\d+>", " ", getattr(message, "content", "") or "").strip()
        async with message.channel.typing():
            text, xray = await slip_review(self, message.guild.id, message.author, slip, question)
        if slip.get("_unsure") and not filed_note:
            text = (f"⚠️ I wasn't sure about {', '.join(clip(u, 60) for u in slip['_unsure'][:3])} on this screenshot, "
                    "so double-check the legs below.\n\n" + text)
        if filed_note:
            text = text.replace("Not logged. Tap 🧾 to file it. Staff can put it under someone else.", filed_note)
        else:
            who = (get_slip_draft(message.guild.id, image_message.id) or {}).get("for_name")
            if who:
                text = text.replace("Not logged. Tap 🧾 to file it. Staff can put it under someone else.",
                                    f"Not logged. Tap 🧾 to file it under **{who}**.")
        logged = db().execute("SELECT id FROM picks WHERE guild_id = ? AND slip_url = ?",
                              (message.guild.id, image_message.jump_url)).fetchone()
        chunks = split_message(text)
        first = None
        for k, chunk in enumerate(chunks):
            extra = {}
            if k == 0 and xray is not None:
                extra["file"] = xray
            if k == len(chunks) - 1 and not logged:
                extra["view"] = slip_draft_view(image_message.id, review=False)
            if k == 0:
                first = await message.reply(chunk, mention_author=False, allowed_mentions=discord.AllowedMentions.none(),
                                            **extra)
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none(), **extra)
        # their own slip, still on the entry screen: it becomes a ghost so we can tell them how the pass worked out
        if not logged and image_message.author.id == message.author.id and slip.get("placed") is False:
            add_ghost(message.guild.id, message.author.id, message.author.display_name, image_message.id,
                      message.channel.id, getattr(first, "id", None), slip)
        await offer_data_picks(message, slip)


