    e.add_field(name="Good passes", value=f"**{pr['good']}**" + (f" · saved {money(pr['saved'])}" if pr["saved"] else ""))
    e.add_field(name="Would've hit", value=f"**{pr['bad']}**" + (f" · {money(pr['missed'])} left on the table"
                                                               if pr["missed"] else ""))
